"""Procedural sound effects: tick, pop, hit, whoosh. Generated by ffmpeg from a fixed recipe (seeded
noise, no third-party sample), so there is nothing to license or credit and the same kind gives the same
WAV byte for byte. Mono 48 kHz, peaking around -3 dBFS: the mix sets the level (`gain_db`)."""
from __future__ import annotations

import os
import re
import subprocess
from pathlib import Path

from . import config
from .safety import safe_path

VERSION = "2"  # part of the cache name: change a recipe, bump this
SR = 48000
RECIPES = {
    "tick": "sine=frequency=1800:duration=0.05,afade=t=out:st=0:d=0.05",
    "pop": "sine=frequency=520:duration=0.09,afade=t=in:d=0.005,afade=t=out:st=0.005:d=0.085",
    "hit": "sine=frequency=95:duration=0.35,lowpass=f=400,afade=t=out:st=0:d=0.35",
    "whoosh": "anoisesrc=duration=0.55:color=pink:seed=7:sample_rate=48000,highpass=f=350,lowpass=f=5000,"
              "afade=t=in:d=0.25,afade=t=out:st=0.25:d=0.3",
}
KINDS = tuple(RECIPES)


def synth(kind: str) -> Path:
    """The WAV for `kind`, generated once into /work/sfx/."""
    if kind not in RECIPES:
        raise ValueError(f"sfx kind must be one of {sorted(RECIPES)} (got {kind!r})")
    p = config.WORK / "sfx" / f"{kind}-v{VERSION}.wav"
    if not p.exists():
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_suffix(f".{os.getpid()}.tmp.wav")
        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-f", "lavfi", "-i", RECIPES[kind],
                        "-af", "volume=15dB,alimiter=limit=0.7:level=disabled,aresample=48000", "-ac", "1", "-ar", str(SR),
                        "-fflags", "+bitexact", "-flags:a", "+bitexact", "-c:a", "pcm_s16le", str(tmp)], check=True)
        tmp.replace(p)
    return p


GAIN_DEFAULT_DB = -14.0
DENSITY_S = 2.0  # lint: more than one effect per this many seconds is clutter


def library_file(e: dict) -> Path | None:
    """The staged clip of a library effect (`path` under /sfx), or None when it is not there."""
    p = e.get("path")
    if not isinstance(p, str) or not p:
        return None
    try:
        f = safe_path(p, [config.SFX_DIR])
    except PermissionError:
        return None
    return f if f.is_file() else None


def source(e: dict) -> Path | None:
    """The WAV/MP3 an entry plays: its staged library clip, else the procedural `kind`."""
    if e.get("path"):
        return library_file(e)
    return synth(e["kind"]) if e.get("kind") in RECIPES else None


def events(spec: dict, tl: dict, cue_t: dict | None = None) -> list[tuple[float, Path, float]]:
    """(start_s, file, gain_db) of every scene.sfx entry, on the video timeline. `spec.audio.sfx: false`
    turns all of them off. `at` is seconds from the start of its scene, or "cue:N" = the moment the voice
    says scene.cues[N].on (`cue_t[scene id][N]`, absolute seconds). A cue that did not resolve, a clip
    that is not staged or a licence that is not CC0/PD plays nothing: silence, never a guess."""
    if (spec.get("audio") or {}).get("sfx") is False:
        return []
    out = []
    for sc, t in zip(spec["scenes"], tl["scenes"]):
        for e in sc.get("sfx") or []:
            if not isinstance(e, dict):
                continue
            at, f = e.get("at"), source(e)
            if e.get("path") and verdict(e.get("license")) != "allow":
                continue
            if isinstance(at, str):
                n = cue_index(at)
                when = (cue_t or {}).get(sc["id"], {}).get(n) if n is not None else None
            elif isinstance(at, (int, float)) and not isinstance(at, bool):
                when = t["start"] / tl["fps"] + max(0.0, float(at))
                if when >= (t["start"] + t["dur"]) / tl["fps"]:
                    continue  # past its own scene: it would land on the next one
            else:
                when = None
            if f is None or when is None:
                continue
            g = e.get("gain_db", GAIN_DEFAULT_DB)
            out.append((when, f, float(g) if isinstance(g, (int, float)) and -40 <= g <= 0 else GAIN_DEFAULT_DB))
    return sorted(out)


def cue_index(at) -> int | None:
    m = re.fullmatch(r"cue:(\d+)", at) if isinstance(at, str) else None
    return int(m.group(1)) if m else None


def verdict(lic) -> str:
    """Library effects are CC0 / public domain only: a credit line per 0.3 s effect is not worth it."""
    from .spec import music_verdict
    return music_verdict(str(lic or ""))


def track(spec: dict, tl: dict, dest: Path, cue_t: dict | None = None) -> Path | None:
    """One WAV with every effect placed at its time, or None when the spec has none."""
    ev = events(spec, tl, cue_t)
    if not ev:
        return None
    cmd = ["ffmpeg", "-y", "-loglevel", "error"]
    for _, f, _g in ev:
        cmd += ["-i", str(f)]
    parts = "".join(f"[{i}]aresample={SR},aformat=channel_layouts=mono,adelay={int(round(t * 1000))}:all=1,volume={g}dB[a{i}];"
                    for i, (t, _f, g) in enumerate(ev))
    mix = "".join(f"[a{i}]" for i in range(len(ev)))
    total = tl["frames"] / tl["fps"]
    dest.parent.mkdir(parents=True, exist_ok=True)
    cmd += ["-filter_complex", f"{parts}{mix}amix=inputs={len(ev)}:normalize=0:dropout_transition=0,apad",
            "-t", f"{total:.3f}", "-ac", "1", "-ar", str(SR), str(dest)]
    subprocess.run(cmd, check=True)
    return dest


def credits(spec: dict) -> list[str]:
    """CREDITS.txt lines for the library effects the spec uses (CC0/PD: traceability, not an obligation)."""
    seen, out = set(), []
    for sc in spec["scenes"]:
        for e in sc.get("sfx") or []:
            if isinstance(e, dict) and e.get("path") and e["path"] not in seen and verdict(e.get("license")) == "allow" \
                    and (spec.get("audio") or {}).get("sfx") is not False:
                seen.add(e["path"])
                head = " · ".join(str(x) for x in (e.get("title"), e.get("creator"), e.get("license"), e.get("source_url")) if x)
                out.append(f"- {head or e['path']}")
    return out
